import * as React from "react";
import { useState, useEffect, useCallback } from 'react';
import HtmlEditorCard from "../../../HHHH-UI/editors/HtmlEditor/HtmlEditor";
import AddCommentComponent from './AddCommentComponent';
import Example from "./SubCommentComponent";
import pnp from 'sp-pnp-js';
import Moment from "moment-timezone";
import ApprovalHistoryPopup from "./ApprovalHistoryPopup";
import { Avatar, Tooltip as InfoToolTip, useId } from "@fluentui/react-components";
import QATestedComponent from './QATestedComponent';
import WorkingActionSubPointsComponent from './WorkingActionSubPointsComponent';

const TOOLTIP_MOUNT = typeof document !== "undefined" ? document.body : undefined;
const SIMPLE_TOOLTIP_CLASS =
    "WAtooltip rounded-md border border-gray-200 bg-white text-xs font-normal text-gray-800 shadow-md";

const trafficLightClass = (active: boolean, color: "red" | "yellow" | "green") => {
    const map = {
        red: active ? "border-[#DC2626] bg-[#DC2626]" : "border-[#DC2626] bg-white hover:bg-red-50",
        yellow: active ? "border-[#F59E0B] bg-[#F59E0B]" : "border-[#F59E0B] bg-white hover:bg-amber-50",
        green: active ? "border-[#16A34A] bg-[#16A34A]" : "border-[#16A34A] bg-white hover:bg-green-50",
    };
    return `inline-block h-3.5 w-3.5 cursor-pointer rounded-full border-2 transition-all duration-200 ${map[color]}`;
};

let indexes: any
let checkValue: any
let commentCheck: any
const CommentBoxComponent = (commentData: any) => {
    const Context = commentData.Context;
    const qaContentId = useId("qaContent");
    const [commentArray, setCommentArray] = useState<any[]>([])
    const CallBack = commentData.callBack;
    const [postBtnStatus, setPostBtnStatus] = useState(false);
    const [currentIndex, setCurrentIndex] = useState('');
    const [isCurrentUserApprover, setIsCurrentUserApprover] = useState(false);
    const [FirstFeedBackArray, setFirstFeedBackArray] = useState<any[]>([]);
    const [currentUserData, setCurrentUserData] = useState<any>([]);
    const [ApprovalPointUserData, setApprovalPointUserData] = useState<any>([]);
    const [ApprovalPointCurrentIndex, setApprovalPointCurrentIndex] = useState('');
    const [ApprovalPointHistoryStatus, setApprovalPointHistoryStatus] = useState(false);
    const [count, setCount] = useState<any>(0);
    var Array: any = [];
    let ApprovalStatus: any = commentData.ApprovalStatus;
    let SmartLightPercentStatus: any = commentData.SmartLightPercentStatus;
