import { useBoolean } from "@fluentui/react-hooks";
import {
  HiOutlinePencilSquare,
  HiOutlineArrowUturnLeft,
  HiOutlineTrash,
} from "react-icons/hi2";
import * as globalCommon from "../../../HHHH-SP-Code/services/globalCommon";
import { DynamicAlert } from "../../../HHHH-UI/alerts/DynamicAlert";
import { devSuccess } from "../../../HHHH-Core/common/Utils";
import Modal from "../Modal";

const approvalBorderClass = (status: string) => {
  if (status === "Reject") return "border-l-4 border-[#DC2626]";
  if (status === "Maybe") return "border-l-4 border-[#F59E0B]";
  if (status === "Approve") return "border-l-4 border-[#16A34A]";
  return "";
};

const AddCommentComponent = (FbData: any) => {
  const FeedBackData = FbData.Data?.length > 0 ? FbData.Data : [];
  const Context = FbData.Context;
  const PortfolioItemColor = FbData.PortfolioItemColor;
  const [FeedBackArray, setFeedBackArray] = useState<any[]>([]);
  const [postTextInput, setPostTextInput] = useState("");
  const [currentUserData, setCurrentUserData] = useState<any>([]);
  const [editPostPanel, setEditPostPanel] = useState(false);
  const [MarkAsApproval, setMarkAsApproval] = useState(false);
  const [buttondisabled, setbuttondisabled] = React.useState(true);
  const [updateComment, setUpdateComment] = useState<any>({
    Title: "",
    Index: "",
    SubTextIndex: "",
    isApprovalComment: false,
    ReplyMessages: [],
  });
  const [ApprovalPointUserData, setApprovalPointUserData] = useState<any>([]);
  const [ApprovalPointCurrentIndex, setApprovalPointCurrentIndex] = useState("");
  const [ApprovalPointHistoryStatus, setApprovalPointHistoryStatus] = useState(false);
  const ApprovalStatus = FbData.ApprovalStatus;
  const SmartLightStatus = FbData.SmartLightStatus;
  const [, { toggle: toggleIsCalloutVisible }] = useBoolean(false);
  const [currentDataIndex, setCurrentDataIndex] = useState<any>(0);
  const [ReplyMessageText, setReplyMessageText] = useState("");
  const [buttonId, setButtonId] = useState(``);
  const [EditModelUsedFor, setEditModelUsedFor] = useState("");
  var Array: any = [];
  const userTimeZone: string = Intl.DateTimeFormat().resolvedOptions().timeZone;

  useEffect(() => {
    devSuccess(FeedBackData);
    let tempArray: any = [];
    if (FeedBackData != null && FeedBackData?.length > 0) {
      FeedBackData.map((dataItem: any) => {
        let checkURL: any = dataItem.AuthorImage?.includes(
          "https://www.hochhuth-consulting.de/sp"
        );
        if (checkURL) {
          dataItem.AuthorImage = dataItem.AuthorImage.replace(
            "https://www.hochhuth-consulting.de/sp",
            "https://hhhhteams.sharepoint.com/sites/HHHH/SP"
          );
        }
        if (dataItem.ApproverData == undefined) {
          dataItem.ApproverData = [];
        }
        Array.push(dataItem);
        tempArray.push(dataItem);
      });
      setFeedBackArray(tempArray);
    } else {
      setFeedBackArray([]);
    }
    getCurrentUserDetails();
  }, [FbData.Data?.length]);

  React.useEffect(() => {
    setTimeout(() => {
      const panelMain: any = document.querySelector(".ms-Panel-main");
      if (panelMain && PortfolioItemColor != "") {
        panelMain.style.setProperty("--SiteColor", PortfolioItemColor);
      }
    }, 2000);
  }, [editPostPanel, PortfolioItemColor]);

  const openEditModal = (
    comment: any,
    indexOfUpdateElement: any,
    indexOfSubtext: any,
    isSubtextComment: any,
    usedFor: any
  ) => {
    setUpdateComment({
      Title: comment,
      Index: indexOfUpdateElement,
      SubTextIndex: indexOfSubtext,
      isApprovalComment: false,
    });
    setEditPostPanel(true);
    setEditModelUsedFor(usedFor);
  };

  const clearComment = async (
    isSubtextComment: any,
    indexOfDeleteElement: any,
    indexOfSubtext: any
  ) => {
    var flag: any = await DynamicAlert("DeleteComment");
    if (flag) {
      let tempArray: any = [];
      FeedBackArray?.map((item: any, index: any) => {
        if (index != indexOfDeleteElement) tempArray.push(item);
      });
      setFeedBackArray(tempArray);
      FbData.callBack(isSubtextComment, tempArray, indexOfSubtext);
    }
  };

  const handleChangeInput = (e: any) => setPostTextInput(e.target.value);

  const getCurrentUserDetails = async () => {
    let currentUserId = Context.pageContext._legacyPageContext.userId;
    if (currentUserId != undefined && FbData.allUsers?.length > 0) {
      FbData.allUsers?.map((userData: any) => {
        if (userData.AssingedToUserId == currentUserId) {
          setCurrentUserData({
            Title: userData.Title,
            Id: userData.AssingedToUserId,
            ImageUrl: userData.Item_x0020_Cover?.Url,
            ApprovalDate: Moment(new Date()).tz(userTimeZone).format("DD MMM YYYY HH:mm"),
          });
        }
      });
    }
  };

  const PostButtonClick = (status: any, Index: any) => {
    if (!postTextInput?.length) {
      DynamicAlert("AddComment");
      return;
    }
    let temp: any = {
      AuthorImage: currentUserData?.ImageUrl ?? "",
      AuthorName:
        currentUserData?.Title ?? Context.pageContext._user.displayName,
      Created: Moment(new Date()).tz(userTimeZone).format("DD MMM YYYY HH:mm"),
      Title: postTextInput,
      NewestCreated: new Date().getTime(),
      editableItem: false,
      isApprovalComment: MarkAsApproval,
      isShowLight: MarkAsApproval ? SmartLightStatus : "",
      ReplyMessages: [],
    };
    FeedBackArray.unshift(temp);
    setPostTextInput("");
    FbData.callBack(status, FeedBackArray, Index);
    setMarkAsApproval(false);
  };

  const editPostCloseFunction = (type?: any, CommentData?: any, usedFor?: any) => {
    if (type == "save") {
      if (usedFor == "ParentComment") {
        FeedBackArray[CommentData.Index].Title = updateComment?.Title;
        FbData.callBack(true, FeedBackArray, FbData?.UXStatus ? CommentData?.SubTextIndex : FbData.index);
      }
      if (usedFor == "ReplyComment") {
        FeedBackArray[CommentData.SubTextIndex].ReplyMessages[CommentData.Index].Title = updateComment?.Title;
        FbData.callBack(true, FeedBackArray, FbData?.UXStatus ? CommentData?.SubTextIndex : FbData.index);
      }
    }
    setEditPostPanel(false);
  };

  const updateCommentFunction = (e: any) => {
    setUpdateComment((prev: any) => ({ ...prev, Title: e.target.value }));
  };

  const cancelCommentBtn = () => FbData.CancelCallback(true);

  const ApprovalHistoryPopupCallBack = useCallback(() => {
    setApprovalPointHistoryStatus(false);
  }, []);

  const OpenCallOutFunction = (IndexData: any) => {
    setCurrentDataIndex(IndexData);
    setButtonId("ReplyBtn" + IndexData);
    toggleIsCalloutVisible();
    setbuttondisabled(true);
  };

  const SaveReplyMessageFunction = async () => {
    setbuttondisabled(false);
    if (!ReplyMessageText?.length) {
      await DynamicAlert("commentReply");
      return;
    }
    if (!FeedBackArray[currentDataIndex].ReplyMessages) {
      FeedBackArray[currentDataIndex].ReplyMessages = [];
    }
    FeedBackArray[currentDataIndex].ReplyMessages.push({
      AuthorImage: currentUserData?.ImageUrl ?? "",
      AuthorName: currentUserData?.Title ?? Context.pageContext._user.displayName,
      Created: Moment(new Date()).tz(userTimeZone).format("DD MMM YYYY HH:mm"),
      Title: ReplyMessageText,
    });
    FbData.callBack(true, FeedBackArray, FbData.index);
    setReplyMessageText("");
    setButtonId("");
  };

  const DeleteReplyMessageFunction = async (ReplyMsgIndex: any, ParentIndex: any) => {
    var flag: any = await DynamicAlert("DeleteComment");
    if (flag) {
      const tempArray = FeedBackArray.map((item: any, index: any) => {
        if (index == ParentIndex) {
          item.ReplyMessages.splice(ReplyMsgIndex, 1);
        }
        return item;
      });
      setFeedBackArray(tempArray);
      FbData.callBack(true, tempArray, FbData.index);
    }
  };

  const renderCommentRow = (
    commentDtl: any,
    index: number,
    isReply = false,
    parentIndex?: number
  ) => (
    <div
      key={isReply ? `reply-${parentIndex}-${index}` : index}
      className={`mb-3 border border-[#dee2e6] bg-white p-3 ${!isReply ? approvalBorderClass(commentDtl.isShowLight) : "ml-4 sm:ml-6"}`}
      title={commentDtl.isShowLight}
    >
      <div className="flex items-start gap-3">
        <Avatar
          className="h-8 w-8 shrink-0 !rounded-full !overflow-hidden [&_img]:!rounded-full [&_img]:object-cover"
          name={commentDtl?.AuthorName}
          title={commentDtl?.AuthorName}
          image={{
            src:
              commentDtl.AuthorImage != undefined &&
              commentDtl.AuthorImage != "" &&
              commentDtl.AuthorImage,
          }}
        />
        <div className="min-w-0 flex-1">
          <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
            <span className="text-sm font-semibold text-[#212529]">
              {commentDtl.AuthorName} - {commentDtl.Created}
            </span>
            <div className="flex shrink-0 items-center gap-1">
              {!isReply && (
                <Popover
                  size="medium"
                  withArrow
                  positioning="above"
                  open={buttonId == "ReplyBtn" + index}
                  onOpenChange={() => OpenCallOutFunction(index)}
                >
                  <PopoverTrigger disableButtonEnhancement>
                    <button type="button" title="Comment Reply" className="inline-flex h-8 w-8 items-center justify-center border-0 bg-transparent p-0 text-[#2F5596] hover:opacity-80" aria-label="Reply to comment">
                      <HiOutlineArrowUturnLeft className="h-4 w-4" />
                    </button>
                  </PopoverTrigger>
                  <PopoverSurface tabIndex={-1} className="comment-reply-popover min-w-[320px] rounded-md border border-[#dee2e6] !bg-white p-3 shadow-md" style={{ background: "#ffffff" }}>
                    <div className="mb-2 text-[21px] font-semibold text-[var(--SiteColor)]">Comment Reply</div>
                    <textarea
                      className="min-h-[80px] w-full resize-y border border-[#ced4da] bg-white px-3 py-2 text-sm text-[#212529] placeholder:text-[#6c757d] focus:border-[#2F5596] focus:outline-none focus:ring-1 focus:ring-[#2F5596]"
                      rows={3}
                      value={ReplyMessageText}
                      onChange={(e: any) => setReplyMessageText(e?.target?.value)}
                      placeholder="Write your reply..."
                    />
                    <div data-modal-actions="" className="mt-3 flex justify-end gap-2">
                      <button className="inline-flex items-center justify-center rounded-md border border-[#2F5596] bg-[#2F5596] px-4 py-2 text-sm font-semibold text-white hover:bg-[#244275] disabled:cursor-not-allowed disabled:border-[#adb5bd] disabled:bg-[#adb5bd]" disabled={buttondisabled === false} onClick={SaveReplyMessageFunction}>
                        Save
                      </button>
                      <button className="inline-flex items-center justify-center rounded-md border border-[var(--SiteColor)] bg-white px-4 py-2 text-sm font-semibold text-[var(--SiteColor)] hover:bg-[#f8f9fa]" onClick={() => setButtonId("")}>Cancel</button>
                    </div>
                  </PopoverSurface>
                </Popover>
              )}
              <button
                type="button"
                title="Edit Comment"
                className="inline-flex h-8 w-8 items-center justify-center border-0 bg-transparent p-0 text-[#2F5596] hover:opacity-80"
                aria-label="Edit comment"
                onClick={() =>
                  openEditModal(commentDtl.Title, index, isReply ? parentIndex : FbData?.index, false, isReply ? "ReplyComment" : "ParentComment")
                }
              >
                <HiOutlinePencilSquare className="h-4 w-4" />
              </button>
              <button
                type="button"
                title="Delete Comment"
                className="inline-flex h-8 w-8 items-center justify-center border-0 bg-transparent p-0 text-[#dc3545] hover:opacity-80"
                aria-label="Delete comment"
                onClick={() =>
                  isReply
                    ? DeleteReplyMessageFunction(index, parentIndex!)
                    : clearComment(true, index, FbData?.index)
                }
              >
                <HiOutlineTrash className="h-4 w-4" />
              </button>
            </div>
          </div>
          <div className="mt-1 break-words text-sm text-[#212529]">
            <span
              dangerouslySetInnerHTML={{
                __html: globalCommon?.replaceURLsWithAnchorTags(commentDtl.Title),
              }}
            />
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <>
      <div className="w-full space-y-3">
        {FeedBackArray?.length > 0 && (
          <div className="space-y-0">
            {[...FeedBackArray].map((commentDtl: any, index: number) => (
              <div key={index}>
                {renderCommentRow(commentDtl, index)}
                {commentDtl.ReplyMessages?.map((reply: any, replyIndex: number) =>
                  renderCommentRow(reply, replyIndex, true, index)
                )}
              </div>
            ))}
          </div>
        )}

        {FbData.postStatus && (
          <section className="w-full">
            {ApprovalStatus && (
              <div className="mb-2 flex items-center gap-2">
                <input
                  type="checkbox"
                  id="markApprovalComment"
                  onClick={() => setMarkAsApproval(true)}
                  className="h-4 w-4 rounded border-gray-300 accent-[#2b5296]"
                />
                <label htmlFor="markApprovalComment" className="cursor-pointer text-sm text-gray-700">
                  Mark as Approval Comment
                </label>
              </div>
            )}
            <div data-modal-actions="" className="flex w-full items-center gap-2">
              <textarea
                id="txtComment"
                placeholder="Enter your comments"
                value={postTextInput}
                onChange={handleChangeInput}
                rows={2}
                className="min-h-[38px] flex-1 resize-y rounded border border-gray-300 bg-white px-3 py-2 text-sm text-gray-800 outline-none placeholder:text-gray-400 focus:border-[#2b5296]"
              />
              <button
                type="button"
                className="inline-flex shrink-0 items-center justify-center rounded-md border border-[#2b5296] bg-[#2b5296] px-6 py-1.5 text-sm font-medium text-white hover:bg-[#244a82] disabled:cursor-not-allowed disabled:opacity-60"
                disabled={!postTextInput?.length}
                onClick={() => PostButtonClick(FbData.postStatus, FbData.index)}
              >
                Post
              </button>
              <button
                type="button"
                className="inline-flex shrink-0 items-center justify-center rounded-md border border-[#2b5296] bg-white px-4 py-1.5 text-sm font-medium text-[#2b5296] hover:bg-gray-50"
                onClick={cancelCommentBtn}
              >
                Cancel
              </button>
            </div>
          </section>
        )}
      </div>

      <Modal
        isOpen={editPostPanel}
        onDismiss={editPostCloseFunction}
        isBlocking={editPostPanel}
        variant="panel"
        size={400}
        title={<span className="text-[21px] font-semibold text-[var(--SiteColor)]">Update Comment</span>}
        headerExtra={<Tooltip ComponentId="1683" />}
        footerActions={
          <div className="flex items-center justify-end gap-2">
            <button type="button" className="inline-flex items-center justify-center rounded-md border border-[#2F5596] bg-[#2F5596] px-4 py-2 text-sm font-semibold text-white hover:bg-[#244275] disabled:cursor-not-allowed disabled:opacity-60" onClick={() => editPostCloseFunction("save", updateComment, EditModelUsedFor)} disabled={!updateComment.Title.trim().length}>
              Save
            </button>
            <button type="button" className="inline-flex items-center justify-center rounded-md border border-[var(--SiteColor)] bg-white px-4 py-2 text-sm font-semibold text-[var(--SiteColor)] hover:bg-[#f8f9fa]" onClick={editPostCloseFunction}>Cancel</button>
          </div>
        }
      >
        <textarea
          className="min-h-[96px] w-full resize-y border border-[#ced4da] bg-white px-3 py-2 text-sm text-[#212529] placeholder:text-[#6c757d] focus:border-[#2F5596] focus:outline-none focus:ring-1 focus:ring-[#2F5596]"
          id="txtUpdateComment"
          rows={6}
          onChange={updateCommentFunction}
          defaultValue={updateComment?.Title ?? ""}
        />
      </Modal>

      {ApprovalPointHistoryStatus && (
        <ApprovalHistoryPopup
          ApprovalPointUserData={ApprovalPointUserData}
          ApprovalPointCurrentIndex={ApprovalPointCurrentIndex}
          ApprovalPointHistoryStatus={ApprovalPointHistoryStatus}
          callBack={ApprovalHistoryPopupCallBack}
        />
      )}
    </>
  );
};

export default AddCommentComponent;

