                    ? { ...b, Subtext: (b.Subtext || []).map((s, si) => (si === subIdx ? { ...s, Title: val } : s)) }
                    : b,
            ),
        );
    };

    // Task-level comment section: bind to the FIRST Description box's Comments (index 0) so it
    // round-trips into the Edit popup, which reads FeedBackDescriptions[0] (EditTaskPopup.tsx:8930-8935;
    // CommentBoxComponent manages box index 0). AddCommentComponent always passes the full updated
    // comment array back as the 2nd callback arg; write it onto box 0, creating a box if none exists
    // yet so the comments have a home at save. Mirrors the emit(boxes.map(...)) pattern (changeBoxTitle).
    const changeComments = (comments: any[]): void => {
        const next = Array.isArray(comments) ? comments : [];
        const base = boxes.length > 0 ? boxes : [makeBox(true)];
        emit(base.map((b, i) => (i === 0 ? { ...b, Comments: next, isShowComment: true } : b)));
    };

    return (
        <div className="mt-2 w-full">
            {boxes.length === 0 ? (
                <button type="button" className={addBtnClass} onClick={addBox}>
                    Add New Box
                </button>
            ) : (
                <div className="space-y-3">
                    {boxes.map((box, i) => (
                        <div key={box.Id} className="border border-[#e0e0e0] bg-[#fafafa] p-3">
                            <div className="flex items-start gap-2">
                                <textarea
                                    className={textareaClass}
                                    rows={2}
                                    placeholder="Describe this point"
                                    value={box.Title}
                                    onChange={(e) => changeBoxTitle(i, e.target.value)}
                                />
                                <span
                                    title="Remove box"
                                    className="svg__iconbox svg__icon--trash hreflink cursor-pointer mt-1"
                                    onClick={() => removeBox(i)}
                                ></span>
                            </div>

                            {(box.Subtext || []).length > 0 && (
                                <div className="mt-2 space-y-2 pl-4">
                                    {(box.Subtext || []).map((sub, s) => (
                                        <div key={sub.Id} className="flex items-start gap-2">
                                            <textarea
                                                className={textareaClass}
                                                rows={1}
                                                placeholder="Sub-text"
                                                value={sub.Title}
                                                onChange={(e) => changeSubBoxTitle(i, s, e.target.value)}
                                            />
                                            <span
                                                title="Remove sub-text box"
                                                className="svg__iconbox svg__icon--trash hreflink cursor-pointer mt-1"
                                                onClick={() => removeSubBox(i, s)}
                                            ></span>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <div className="mt-2">
                                <a
                                    className="text-xs text-(--SiteColor) hover:underline font-medium cursor-pointer"
                                    onClick={() => addSubBox(i)}
                                >
                                    + Add Sub-Text Box
                                </a>
                            </div>
                        </div>
                    ))}
                    <button type="button" className={addBtnClass} onClick={addBox}>
                        Add New Box
                    </button>
                </div>
            )}
        </div>
    );
}

