useEffect(() => {
    try {
        $("#spPageCanvasContent").removeClass(); $("#spPageCanvasContent").addClass("hundred"); $("#workbenchPageContent").removeClass(); $("#workbenchPageContent").addClass("hundred");
    } catch (e) { }
    const initAnchor = (SelectedDayDate != undefined && SelectedDayDate != '') ? moment(SelectedDayDate, 'DD/MM/YYYY') : moment();
    setWeekdays(getUpcomingWeekdays(initAnchor));
    fetchSubsitesWithPermissions(true);
    loadTaskUsers('');
}, []);
useEffect(() => {
    if (hasFetchedBroadTasks.current) return;
    if (!validSites || validSites.length === 0) return;
    // Wait until the first list has painted so the second pass cannot
    // replace All (23) with All (0) before that batch is on screen.
    if (!firstGetAllDataDone.current) return;
    hasFetchedBroadTasks.current = true;
    broadTasksLoadInFlightRef.current = true;
    setIsBroadTasksLoading(true);

    let unmounted = false;
    const timer = setTimeout(async () => {
        let data: any[] = [];
        try {
            if (AllData == undefined || AllData?.length <= 1500) {
                // Was 'PercentComplete le 0.80' with no date bound — stricter than the
                // primary fetch's 90% cutoff, so 81-90% tasks quiet >14 days matched
                // neither query and never appeared anywhere. Align threshold to close that gap.
                const broadStartISO = moment().subtract(2, 'years').startOf('day').toDate().toISOString();
                const broadFilter = `(Modified ge '${broadStartISO}') and (PercentComplete le 0.90)`;
                const fetchPromises = validSites.map(async (subsite: any) => {
                    try {
                        const result: any = await globalCommon?.loadAllSiteTaskData(
                            subsite,
                            broadFilter
                        );
                        return result;
                    } catch {
                        return [];
                    }
                });
                const results: any = await Promise.all(fetchPromises);
                data = [].concat.apply([], results);
            }

            const map = new Map();
            const uniqueData: any[] = [];
            for (const item of data) {
                try {
                    item.copyTeamMembers = JSON.parse(JSON.stringify(item?.TeamMembers || []));
                    item.copyResponsibleTeam = JSON.parse(JSON.stringify(item?.ResponsibleTeam || []));
                } catch (e) { }
                const key = `${item.Id}-${item.siteType}`;
                if (!map.has(key)) {
                    map.set(key, true);
                    uniqueData.push(item);
                }
            }
            AllData = [
                ...(AllData ?? []),
                ...uniqueData.filter((item) =>
                    !(AllData ?? []).some((existing: any) =>
                        existing?.Id == item?.Id && existing?.siteType == item?.siteType
                    )
                )
            ];
            AllDataDirty = true;
            if (unmounted) return;
            const activeDateStr = SelectedPickerDate || omtSelectedDateStr || SelectedDate || '';
            let activeFilter = LocalselectedFilter != undefined && LocalselectedFilter !== ''
                ? LocalselectedFilter
                : 'AllTask';
            if (activeFilter === 'hhhhootb-pane') activeFilter = 'AllTask';
            const actionFilter = selectedActionFilterRef.current && activeFilter != 'All'
                ? selectedActionFilterRef.current
                : '';
            await getAllData(
                false,
                activeFilter,
                activeDateStr,
                actionFilter,
                true
            );
        } finally {
            if (!unmounted) {
                broadTasksLoadInFlightRef.current = false;
                setIsBroadTasksLoading(false);
                setisLoadingTask(false);
            }
        }
    }, 2000);

